"},{"relativePath":"schema.ts","content":"export const INSPECTION_RESULT_EVENT = "app.inspection.result";

export type InspectionStatusKind = "passed" | "failed" | "other";

export type InspectionCheck = {
  name: string;
  status: string;
  statusKind: InspectionStatusKind;
  detail: unknown;
};

export type InspectionResultData = {
  target: string | null;
  checks: InspectionCheck[];
  passedCount: number;
  failedCount: number;
  otherCount: number;
};

export type ParsedInspectionResult =
  | { success: true; data: InspectionResultData }
  | { success: false };

const FAILED_STATUSES = new Set(["failed", "fail", "failure", "error", "broken", "unhealthy"]);
const PASSED_STATUSES = new Set(["passed", "pass", "ok", "success", "succeeded", "healthy"]);
const PRIMARY_DETAIL_KEYS = new Set(["code", "message", "duration_ms"]);

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function classifyStatus(status: string): InspectionStatusKind {
  const normalized = status.trim().toLowerCase();
  if (FAILED_STATUSES.has(normalized)) return "failed";
  if (PASSED_STATUSES.has(normalized)) return "passed";
  return "other";
}

export function parseInspectionResult(value: unknown): ParsedInspectionResult {
  if (!isRecord(value) || !Array.isArray(value.checks)) {
    return { success: false };
  }

  const checks: InspectionCheck[] = [];
  for (const entry of value.checks) {
    if (!isRecord(entry)) continue;
    const name = typeof entry.name === "string" ? entry.name.trim() : "";
    if (!name) continue;
    const status = typeof entry.status === "string" ? entry.status.trim() : "";
    checks.push({
      name,
      status,
      statusKind: classifyStatus(status),
      detail: entry.detail ?? null,
    });
  }

  const target = typeof value.target === "string" && value.target.trim() ? value.target.trim() : null;
  let passedCount = 0;
  let failedCount = 0;
  let otherCount = 0;
  for (const check of checks) {
    if (check.statusKind === "passed") passedCount += 1;
    else if (check.statusKind === "failed") failedCount += 1;
    else otherCount += 1;
  }

  return {
    success: true,
    data: { target, checks, passedCount, failedCount, otherCount },
  };
}

export type DetailFields = {
  code: string | null;
  message: string | null;
  durationMs: number | null;
  extra: Array<{ key: string; value: string }>;
};

function stringifyValue(value: unknown): string {
  if (typeof value === "string") return value;
  try {
    const serialized = JSON.stringify(value);
    return serialized === undefined ? String(value) : serialized;
  } catch {
    return String(value);
  }
}

export function readDetailFields(detail: unknown): DetailFields {
  const empty: DetailFields = { code: null, message: null, durationMs: null, extra: [] };
  if (detail === null || detail === undefined) return empty;
  if (typeof detail === "string") return { ...empty, message: detail.trim() || null };
  if (typeof detail === "number" || typeof detail === "boolean") {
    return { ...empty, message: String(detail) };
  }
  if (!isRecord(detail)) return empty;

  const code = typeof detail.code === "string" && detail.code.trim() ? detail.code.trim() : null;
  const message = typeof detail.message === "string" && detail.message.trim() ? detail.message.trim() : null;
  const durationRaw = detail.duration_ms;
  const durationMs = typeof durationRaw === "number" && Number.isFinite(durationRaw) ? durationRaw : null;

  const extra: Array<{ key: string; value: string }> = [];
  for (const [key, raw] of Object.entries(detail)) {
    if (PRIMARY_DETAIL_KEYS.has(key)) continue;
    if (raw === null || raw === undefined) continue;
    extra.push({ key, value: stringifyValue(raw) });
  }

  return { code, message, durationMs, extra };
}

export function serializeCheckForCopy(check: InspectionCheck): string {
  const payload: Record<string, unknown> = { name: check.name, status: check.status };
  if (check.detail !== null && check.detail !== undefined) {
    payload.detail = check.detail;
  }
  try {
    return JSON.stringify(payload, null, 2);
  } catch {
    return `${check.name}: ${check.status}`;
  }
}
"},{"relativePath":"messages.ts","content":"import type { AgentUILocaleCode } from "@za38.03/agent-ui-plugins";

export type InspectionCopy = {
  title: string;
  cardLabel: (target: string | null) => string;
  summary: (counts: { passed: number; failed: number; other: number }) => string;
  failedHeading: string;
  passedHeading: string;
  otherHeading: string;
  emptyChecks: string;
  invalid: string;
  expandLabel: (name: string) => string;
  collapseLabel: (name: string) => string;
  copyAction: string;
  copyLabel: (name: string) => string;
  copied: string;
  copyFailed: string;
  codeLabel: string;
  messageLabel: string;
  durationLabel: string;
  noDetail: string;
  durationValue: (milliseconds: number) => string;
  statusValue: (status: string) => string;
};

const zhCN: InspectionCopy = {
  title: "检查结果",
  cardLabel: (target) => (target ? `检查结果：${target}` : "检查结果"),
  summary: ({ passed, failed, other }) => {
    const parts = [`通过 ${passed} 项`, `失败 ${failed} 项`];
    if (other > 0) parts.push(`其他 ${other} 项`);
    return parts.join(" · ");
  },
  failedHeading: "未通过",
  passedHeading: "已通过",
  otherHeading: "其他状态",
  emptyChecks: "本次检查没有返回检查项。",
  invalid: "检查结果数据格式不正确。",
  expandLabel: (name) => `展开 ${name} 的失败原因`,
  collapseLabel: (name) => `收起 ${name} 的失败原因`,
  copyAction: "复制错误详情",
  copyLabel: (name) => `复制 ${name} 的错误详情`,
  copied: "已复制",
  copyFailed: "复制失败，请手动选中文本",
  codeLabel: "错误码",
  messageLabel: "说明",
  durationLabel: "耗时",
  noDetail: "没有更多错误详情。",
  durationValue: (milliseconds) => `${milliseconds} 毫秒`,
  statusValue: (status) => (status ? `状态：${status}` : "状态未知"),
};

const enUS: InspectionCopy = {
  title: "Inspection result",
  cardLabel: (target) => (target ? `Inspection result: ${target}` : "Inspection result"),
  summary: ({ passed, failed, other }) => {
    const parts = [`${passed} passed`, `${failed} failed`];
    if (other > 0) parts.push(`${other} other`);
    return parts.join(" · ");
  },
  failedHeading: "Failed",
  passedHeading: "Passed",
  otherHeading: "Other statuses",
  emptyChecks: "This inspection returned no checks.",
  invalid: "The inspection result data is not valid.",
  expandLabel: (name) => `Show failure reason for ${name}`,
  collapseLabel: (name) => `Hide failure reason for ${name}`,
  copyAction: "Copy error details",
  copyLabel: (name) => `Copy error details for ${name}`,
  copied: "Copied",
  copyFailed: "Copy failed. Select the text manually.",
  codeLabel: "Code",
  messageLabel: "Message",
  durationLabel: "Duration",
  noDetail: "No further error details.",
  durationValue: (milliseconds) => `${milliseconds} ms`,
  statusValue: (status) => (status ? `Status: ${status}` : "Status unknown"),
};

const copyByLocale: Partial<Record<AgentUILocaleCode, InspectionCopy>> = {
  "zh-CN": zhCN,
  "en-US": enUS,
};

export function getInspectionCopy(locale: AgentUILocaleCode): InspectionCopy {
  return copyByLocale[locale] ?? zhCN;
}
"},{"relativePath":"index.tsx","content":"import { defineDataMessageUI, useAgentUILocaleCode } from "@za38.03/agent-ui-plugins";
import { Fragment, useCallback, useEffect, useRef, useState, type ReactNode } from "react";
import { getInspectionCopy, type InspectionCopy } from "./messages";
import {
  INSPECTION_RESULT_EVENT,
  parseInspectionResult,
  readDetailFields,
  serializeCheckForCopy,
  type InspectionCheck,
} from "./schema";
import "./styles.css";

type CopyFeedback = "copied" | "error";

async function writeClipboard(text: string): Promise<boolean> {
  try {
    const clipboard = typeof navigator === "undefined" ? undefined : navigator.clipboard;
    if (!clipboard?.writeText) return false;
    await clipboard.writeText(text);
    return true;
  } catch {
    return false;
  }
}

function buildDetailRows(
  check: InspectionCheck,
  copy: InspectionCopy,
): Array<{ key: string; label: string; value: ReactNode }> {
  const fields = readDetailFields(check.detail);
  const rows: Array<{ key: string; label: string; value: ReactNode }> = [];
  if (fields.code) {
    rows.push({ key: "code", label: copy.codeLabel, value: <code>{fields.code}</code> });
  }
  if (fields.message) {
    rows.push({ key: "message", label: copy.messageLabel, value: fields.message });
  }
  if (fields.durationMs !== null) {
    rows.push({ key: "duration", label: copy.durationLabel, value: copy.durationValue(fields.durationMs) });
  }
  for (const extra of fields.extra) {
    rows.push({ key: `extra-${extra.key}`, label: extra.key, value: extra.value });
  }
  return rows;
}

export function InspectionResultMessage({ data }: { data: unknown }) {
  const copy = getInspectionCopy(useAgentUILocaleCode());
  const parsed = parseInspectionResult(data);
  const [expandedKeys, setExpandedKeys] = useState<Record<string, boolean>>({});
  const [feedbacks, setFeedbacks] = useState<Record<string, CopyFeedback>>({});
  const timers = useRef<Record<string, ReturnType<typeof setTimeout>>>({});

  useEffect(() => {
    const pending = timers.current;
    return () => {
      for (const timer of Object.values(pending)) clearTimeout(timer);
    };
  }, []);

  const toggle = useCallback((key: string) => {
    setExpandedKeys((previous) => ({ ...previous, [key]: !previous[key] }));
  }, []);

  const handleCopy = useCallback(async (key: string, check: InspectionCheck) => {
    const succeeded = await writeClipboard(serializeCheckForCopy(check));
    setFeedbacks((previous) => ({ ...previous, [key]: succeeded ? "copied" : "error" }));
    const existing = timers.current[key];
    if (existing) clearTimeout(existing);
    timers.current[key] = setTimeout(() => {
      setFeedbacks((previous) => {
        const next = { ...previous };
        delete next[key];
        return next;
      });
      delete timers.current[key];
    }, 2000);
  }, []);

  if (!parsed.success) {
    return (
      <section className="inspection-result inspection-result--invalid" role="alert">
        <p className="inspection-result__message">{copy.invalid}</p>
      </section>
    );
  }

  const { target, checks, passedCount, failedCount, otherCount } = parsed.data;
  const failed: Array<{ key: string; check: InspectionCheck }> = [];
  const passed: Array<{ key: string; check: InspectionCheck }> = [];
  const other: Array<{ key: string; check: InspectionCheck }> = [];
  checks.forEach((check, index) => {
    const entry = { key: `check-${index}`, check };
    if (check.statusKind === "failed") failed.push(entry);
    else if (check.statusKind === "passed") passed.push(entry);
    else other.push(entry);
  });

  return (
    <section className="inspection-result" aria-label={copy.cardLabel(target)}>
      <header className="inspection-result__header">
        <h3 className="inspection-result__title">{target ?? copy.title}</h3>
        <p className="inspection-result__summary" data-tone={failedCount > 0 ? "failed" : "passed"}>
          {copy.summary({ passed: passedCount, failed: failedCount, other: otherCount })}
        </p>
      </header>

      {failed.length > 0 ? (
        <section className="inspection-result__group" data-tone="failed" aria-label={copy.failedHeading}>
          <h4 className="inspection-result__group-title">{copy.failedHeading}</h4>
          <ul className="inspection-result__list">
            {failed.map(({ key, check }) => {
              const detailId = `inspection-result-detail-${key}`;
              const isExpanded = Boolean(expandedKeys[key]);
              const rows = buildDetailRows(check, copy);
              const feedback = feedbacks[key];
              return (
                <li key={key} className="inspection-result__failed-item">
                  <button
                    type="button"
                    className="inspection-result__failed-header"
                    aria-expanded={isExpanded}
                    aria-controls={detailId}
                    aria-label={isExpanded ? copy.collapseLabel(check.name) : copy.expandLabel(check.name)}
                    onClick={() => toggle(key)}
                  >
                    <span className="inspection-result__failed-name">{check.name}</span>
                    {readDetailFields(check.detail).code ? (
                      <code className="inspection-result__code">{readDetailFields(check.detail).code}</code>
                    ) : null}
                    <span className="inspection-result__chevron" data-expanded={isExpanded} aria-hidden="true" />
                  </button>
                  {isExpanded ? (
                    <div className="inspection-result__detail" id={detailId}>
                      {rows.length > 0 ? (
                        <dl className="inspection-result__detail-list">
                          {rows.map((row) => (
                            <Fragment key={row.key}>
                              <dt>{row.label}</dt>
                              <dd>{row.value}</dd>
                            </Fragment>
                          ))}
                        </dl>
                      ) : (
                        <p className="inspection-result__message">{copy.noDetail}</p>
                      )}
                      <div className="inspection-result__detail-actions">
                        <button
                          type="button"
                          className="inspection-result__copy"
                          onClick={() => void handleCopy(key, check)}
                          aria-label={copy.copyLabel(check.name)}
                        >
                          {copy.copyAction}
                        </button>
                        <span className="inspection-result__copy-feedback" role="status">
                          {feedback === "copied" ? copy.copied : feedback === "error" ? copy.copyFailed : ""}
                        </span>
                      </div>
                    </div>
                  ) : null}
                </li>
              );
            })}
          </ul>
        </section>
      ) : null}

      {passed.length > 0 ? (
        <section className="inspection-result__group" data-tone="passed" aria-label={copy.passedHeading}>
          <h4 className="inspection-result__group-title">{copy.passedHeading}</h4>
          <ul className="inspection-result__list inspection-result__list--compact">
            {passed.map(({ key, check }) => (
              <li key={key} className="inspection-result__passed-item">
                <span className="inspection-result__check" aria-hidden="true">
                  ✓
                </span>
                <span className="inspection-result__name">{check.name}</span>
              </li>
            ))}
          </ul>
        </section>
      ) : null}

      {other.length > 0 ? (
        <section className="inspection-result__group" data-tone="other" aria-label={copy.otherHeading}>
          <h4 className="inspection-result__group-title">{copy.otherHeading}</h4>
          <ul className="inspection-result__list inspection-result__list--compact">
            {other.map(({ key, check }) => (
              <li key={key} className="inspection-result__other-item">
                <span className="inspection-result__name">{check.name}</span>
                <span className="inspection-result__status-chip">{copy.statusValue(check.status)}</span>
              </li>
            ))}
          </ul>
        </section>
      ) : null}

      {checks.length === 0 ? <p className="inspection-result__message">{copy.emptyChecks}</p> : null}
    </section>
  );
}

export const inspectionResultUI = defineDataMessageUI<unknown>({
  name: INSPECTION_RESULT_EVENT,
  render: InspectionResultMessage,
});
"},{"relativePath":"definition.ts","content":"import type { UIPluginDefinition, UIPluginManifest } from "@za38.03/agent-ui-plugins";
