"},{"relativePath":"styles.css","content":".inspection-result {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: 10px;
  width: 100%;
  min-width: 0;
  padding: 12px 14px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--muted);
  color: var(--foreground);
  font-size: 13px;
  line-height: 1.5;
}

.inspection-result--invalid {
  border-color: #fca5a5;
}

.inspection-result__header {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 4px 10px;
}

.inspection-result__title {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
}

.inspection-result__summary {
  margin: 0;
  font-size: 12px;
  opacity: 0.75;
}

.inspection-result__summary[data-tone="failed"] {
  color: #b91c1c;
  font-weight: 600;
  opacity: 1;
}

[data-theme="dark"] .inspection-result__summary[data-tone="failed"] {
  color: #f87171;
}

.inspection-result__group {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}

.inspection-result__group-title {
  margin: 0;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.02em;
  opacity: 0.8;
}

.inspection-result__list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.inspection-result__failed-item {
  overflow: hidden;
  border: 1px solid #fca5a5;
  border-radius: 10px;
  background: #fef2f2;
}

[data-theme="dark"] .inspection-result__failed-item {
  border-color: #7f1d1d;
  background: #2a1313;
}

.inspection-result__failed-header {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 8px 10px;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: start;
  cursor: pointer;
}

.inspection-result__failed-header:hover {
  background: rgba(220, 38, 38, 0.08);
}

.inspection-result__failed-header:focus-visible {
  outline: 2px solid var(--ring, #2563eb);
  outline-offset: -2px;
}

.inspection-result__failed-name {
  font-weight: 600;
  color: #b91c1c;
}

[data-theme="dark"] .inspection-result__failed-name {
  color: #fca5a5;
}

.inspection-result__code {
  padding: 1px 6px;
  border-radius: 999px;
  background: rgba(220, 38, 38, 0.12);
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 11px;
  color: #b91c1c;
}

[data-theme="dark"] .inspection-result__code {
  color: #fca5a5;
}

.inspection-result__chevron {
  width: 8px;
  height: 8px;
  margin-inline-start: auto;
  border-right: 2px solid currentColor;
  border-bottom: 2px solid currentColor;
  transform: rotate(-45deg);
  transition: transform 120ms ease;
  opacity: 0.7;
}

.inspection-result__chevron[data-expanded="true"] {
  transform: rotate(45deg);
}

.inspection-result__detail {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 0 10px 10px;
}

.inspection-result__detail-list {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 4px 10px;
  margin: 0;
  font-size: 12px;
}

.inspection-result__detail-list dt {
  font-weight: 600;
  opacity: 0.8;
}

.inspection-result__detail-list dd {
  margin: 0;
  word-break: break-word;
}

.inspection-result__detail-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.inspection-result__copy {
  padding: 4px 10px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--background, transparent);
  color: var(--foreground);
  font: inherit;
  font-size: 12px;
  cursor: pointer;
}

.inspection-result__copy:hover {
  border-color: #b91c1c;
  color: #b91c1c;
}

[data-theme="dark"] .inspection-result__copy:hover {
  border-color: #f87171;
  color: #f87171;
}

.inspection-result__copy:focus-visible {
  outline: 2px solid var(--ring, #2563eb);
  outline-offset: 2px;
}

.inspection-result__copy-feedback {
  font-size: 12px;
  opacity: 0.85;
}

.inspection-result__passed-item,
.inspection-result__other-item {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.inspection-result__check {
  font-weight: 700;
  color: #15803d;
}

[data-theme="dark"] .inspection-result__check {
  color: #4ade80;
}

.inspection-result__name {
  min-width: 0;
  word-break: break-word;
}

.inspection-result__status-chip {
  padding: 1px 6px;
  border: 1px solid var(--border);
  border-radius: 999px;
  font-size: 11px;
  opacity: 0.85;
}

.inspection-result__message {
  margin: 0;
}
